<?php
require_once __DIR__ . '/../includes/db.php'; require_admin(); $errors=[]; $settings=$pdo->query('SELECT setting_key,setting_value,setting_label FROM settings ORDER BY setting_label')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){foreach($settings as $setting){$value=trim($_POST[$setting['setting_key']]??'');if($setting['setting_key']==='late_fee_per_day'&&(!is_numeric($value)||(float)$value<0)){$errors[]='Late fee per day must be zero or more.';}}if(!$errors){$update=$pdo->prepare('UPDATE settings SET setting_value=? WHERE setting_key=?');foreach($settings as $setting){$update->execute([trim($_POST[$setting['setting_key']]??''),$setting['setting_key']]);}set_flash('success','Settings saved.');redirect('admin/settings.php');}}
$page_title='Settings';require_once __DIR__ . '/../includes/header.php';require __DIR__ . '/_nav.php';
?>
<div class="row"><div class="col-lg-7"><div class="card shadow-sm"><div class="card-body p-4"><h1 class="h4 mb-3">Rental Settings</h1><?php if($errors):?><div class="alert alert-danger"><?php foreach($errors as $error):?><div><?php echo e($error); ?></div><?php endforeach;?></div><?php endif;?><form method="post"><?php foreach($settings as $setting):?><div class="mb-3"><label class="form-label" for="<?php echo e($setting['setting_key']); ?>"><?php echo e($setting['setting_label']); ?></label><input class="form-control" id="<?php echo e($setting['setting_key']); ?>" name="<?php echo e($setting['setting_key']); ?>" value="<?php echo e($setting['setting_value']); ?>" <?php echo $setting['setting_key']==='late_fee_per_day'?'type="number" min="0" step="0.01"':'type="text"'; ?>></div><?php endforeach;?><button class="btn btn-brand">Save Settings</button></form></div></div></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
